"""Author PRE_A1-U14 only; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][13]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(13,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U14.UNDERSTAND';A='PRE_A1.U14.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('matin','fr:matin:morning','le matin','утро; утром (в распорядке)','лё матэ́(н)',ex('Le matin, je lis un livre.','Утром я читаю книгу.','лё матэ(н), жё ли э(н) ли́вр'),1,[rev('matin-meaning',fr('Le matin','лё матэ́(н)'),['Вечер','Утро','Вторая половина дня'],1,'Названо утро.','Правильное значение — утро; вторая половина дня и вечер относятся к другому времени суток.'),rev('matin-use',ru('Нужно передать «Утром я читаю книгу» как часть распорядка. Какую реплику выбрать?'),[fr('L’après-midi, je lis un livre.','лапрэ-миди, жё ли э(н) ли́вр'),fr('Le matin, je lis un livre.','лё матэ(н), жё ли э(н) ли́вр'),fr('Je lis un livre.','жё ли э(н) ли́вр')],1,'В реплике чтение отнесено к утру.','Нужна утренняя рамка; вторая половина дня или реплика без времени не сохраняют условие.')])
addword('apres-midi','fr:apres-midi:afternoon','l’après-midi','вторая половина дня; днём после полудня','лапрэ-миди́',ex('L’après-midi, j’écris un mot.','Во второй половине дня я пишу слово.','лапрэ-миди, жэкри э(н) мо́'),1,[rev('apres-midi-meaning',fr('L’après-midi','лапрэ-миди́'),['Утро','Весь день целиком','Вторая половина дня после полудня'],2,'Это вторая половина дня после полудня.','Нужно значение после полудня; это не утро и не весь день целиком.'),rev('apres-midi-use',ru('Нужно отнести чтение ко второй половине дня после полудня. Какую реплику выбрать?'),[fr('L’après-midi, je lis un livre.','лапрэ-миди, жё ли э(н) ли́вр'),fr('Le matin, je lis un livre.','лё матэ(н), жё ли э(н) ли́вр'),fr('Je lis un livre.','жё ли э(н) ли́вр')],0,'Чтение отнесено к нужной части дня.','Нужна рамка второй половины дня; утренняя рамка и отсутствие времени не подходят.')])
addword('soir','fr:soir:evening','le soir','вечер; вечером (в распорядке)','лё суа́р',ex('Le soir, je regarde la télé.','Вечером я смотрю телевизор.','лё суар, жё рёгард ла тэле́'),2,[rev('soir-meaning',fr('Le soir','лё суа́р'),['Вечер','Утро','Ночь'],0,'Назван вечер.','Правильное значение — вечер; утро и ночь называются иначе.'),rev('soir-use',ru('Нужно передать «Вечером я смотрю телевизор». Какую реплику выбрать?'),[fr('Le matin, je regarde la télé.','лё матэ(н), жё рёгард ла тэле́'),fr('La nuit, je regarde la télé.','ла нюи, жё рёгард ла тэле́'),fr('Le soir, je regarde la télé.','лё суар, жё рёгард ла тэле́')],2,'Просмотр отнесён к вечеру.','Нужна вечерняя рамка; утро и ночь меняют время из условия.')])
addword('nuit','fr:nuit:night','la nuit','ночь; ночью','ла нюи́',ex('Je dors la nuit.','Я сплю ночью.','жё дор ла нюи́'),2,[rev('nuit-meaning',fr('La nuit','ла нюи́'),['Вечер','Ночь','Утро'],1,'Названа ночь.','Нужно значение ночь; вечер и утро — другие части суток.'),rev('nuit-use',ru('Какое сочетание в готовом образце «Я сплю ночью» обозначает именно ночное время?'),[fr('le soir','лё суа́р'),fr('le matin','лё матэ́(н)'),fr('la nuit','ла нюи́')],2,'Выбрана рамка ночного времени.','Нужна ночь; вечер и утро не сохраняют условие.')])
addword('dormir','fr:dormir:sleep','dormir','спать','дорми́р',ex('Je dors la nuit.','Я сплю ночью.','жё дор ла нюи́'),2,[rev('dormir-meaning',fr('Dormir','дорми́р'),['Спать','Смотреть','Читать'],0,'Слово называет сон.','Правильное значение — спать; смотреть и читать означают другие действия.'),rev('dormir-use',ru('Нужно сообщить «Я сплю ночью». Какую реплику выбрать?'),[fr('Je lis un livre.','жё ли э(н) ли́вр'),fr('Je dors la nuit.','жё дор ла нюи́'),fr('Je regarde la télé.','жё рёгард ла тэле́')],1,'Реплика сообщает сон в ночное время.','Нужно «Я сплю ночью»; чтение и просмотр телевизора описывают другие действия.')])
addword('maintenant','fr:maintenant:now','maintenant','сейчас','мэ(н)тёна́(н)',ex('Maintenant, je lis un livre.','Сейчас я читаю книгу.','мэ(н)тёна(н), жё ли э(н) ли́вр'),3,[rev('maintenant-meaning',fr('Maintenant','мэ(н)тёна́(н)'),['Позже','Завтра','Сейчас'],2,'Это метка текущего момента.','Нужно значение сейчас; позже и завтра не обозначают текущий момент.'),rev('maintenant-use',ru('Нужно кратко записать «Встреча сейчас». Какую запись выбрать?'),[fr('Rendez-vous maintenant.','ра(н)дэ-ву мэ(н)тёна́(н)'),fr('Rendez-vous plus tard.','ра(н)дэ-ву плю та́р'),fr('Rendez-vous demain.','ра(н)дэ-ву дёмэ́(н)')],0,'Встреча отнесена к текущему моменту.','Нужно сейчас; позже и завтра меняют время встречи.')])
addword('plus-tard','fr:plus-tard:later','plus tard','позже (без точного указания времени)','плю та́р',ex('Rendez-vous plus tard.','Встреча позже.','ра(н)дэ-ву плю та́р'),3,[rev('plus-tard-meaning',fr('Plus tard','плю та́р'),['Сейчас','Позже, без точного времени','Завтра, с указанным днём'],1,'Выражение означает позже без точного времени.','Позже не означает сейчас и само по себе не указывает завтра.'),rev('plus-tard-use',ru('Нужно записать именно «Встреча позже», не уточняя день. Какую запись выбрать?'),[fr('Rendez-vous demain.','ра(н)дэ-ву дёмэ́(н)'),fr('Rendez-vous maintenant.','ра(н)дэ-ву мэ(н)тёна́(н)'),fr('Rendez-vous plus tard.','ра(н)дэ-ву плю та́р')],2,'Запись сообщает позже без указания дня.','Нужно выражение позже; сейчас и явно названное завтра имеют другой смысл.')])
addword('bonne-nuit','fr:bonne-nuit:bedtime-wish','bonne nuit','спокойной ночи (пожелание перед сном)','бон нюи́',ex('Bonne nuit !','Спокойной ночи!','бон нюи́'),4,[rev('bonne-nuit-meaning',fr('Bonne nuit !','бон нюи́'),['Добрый вечер при встрече','Пожелание спокойной ночи','Добрый день при встрече'],1,'Это пожелание спокойной ночи.','Реплика желает спокойной ночи, а не служит обычным приветствием при приходе.'),rev('bonne-nuit-use',ru('Собеседник уходит спать. Нужно пожелать ему спокойной ночи. Что выбрать?'),[fr('Bonne nuit !','бон нюи́'),fr('Bonsoir !','бо(н)суа́р'),fr('Bonjour !','бо(н)жу́р')],0,'Пожелание подходит перед сном.','Нужно пожелание спокойной ночи; приветствия при встрече имеют другую функцию.')])

def cards(ids):return [wc(x) for x in ids]
s=start(1,'Различайте утро и вторую половину дня в коротких репликах о распорядке. Повторите запись о встрече завтра.',['matin','apres-midi','demain','rendez-vous','lundi','je','lire','livre','ecrire','mot','boire','eau'])
choose(s,'reading',['PRE_A1.U13.APPLY'],['rendez-vous','demain'],['demain'],'Когда назначена встреча в знакомой записи?',fr('Rendez-vous demain.','ра(н)дэ-ву дёмэ́(н).'),['Сегодня','Вчера','Завтра'],2,'Встреча назначена на завтра.','Знакомая метка указывает завтра, а не сегодня или вчера.')
intro(s,2,'Le matin — «утро; утром», l’après-midi — «вторая половина дня после полудня». Второе сочетание не означает весь день целиком. В распорядке используем готовые рамки: Le matin, je lis un livre. — «Утром я читаю книгу»; L’après-midi, j’écris un mot. — «Во второй половине дня я пишу слово». Это образцы о распорядке, без часов и без указания на конкретное сегодняшнее утро.',['matin','apres-midi'],[('Le matin','лё матэ́(н)'),('l’après-midi','лапрэ-миди́'),('Le matin, je lis un livre.','лё матэ(н), жё ли э(н) ли́вр'),('L’après-midi, j’écris un mot.','лапрэ-миди, жэкри э(н) мо́')],('Le matin, je lis un livre. L’après-midi, j’écris un mot.','лё матэ(н), жё ли э(н) ли́вр. лапрэ-миди, жэкри э(н) мо́.'))
pairs(s,[U,'PRE_A1.U13.UNDERSTAND'],[('matin','Утро'),('apres-midi','Вторая половина дня после полудня'),('lundi','Понедельник — день недели')],'Вы различили части суток и знакомый день недели.','Утро и вторая половина дня — части суток; понедельник — название дня недели.')
