page(s,[('Две части дня',['Утро и вторая половина дня после полудня — разные части суток. Название второй половины дня не означает весь день целиком.'],[W['matin']['example'],W['apres-midi']['example']]),('Рамка распорядка',['В изученном образце рамка времени стоит в начале, затем идёт знакомое действие. Эти формы подходят для короткого описания распорядка; конкретное сегодняшнее утро отдельно не вводится.'],[ex('Le matin, je bois de l’eau.','Утром я пью воду.','лё матэ(н), жё буа дё ло́')]),('День недели и часть суток',['Знакомый понедельник называет день недели. Утро и вторая половина дня называют части суток; не подменяйте одну категорию другой.'],[ex('Lundi.','Понедельник.','лё(н)ди́')])])
