choose(s,'reading',[U],['apres-midi','je','ecrire','mot'],['apres-midi'],'Когда происходит действие в знакомом образце?',fr('L’après-midi, j’écris un mot.','лапрэ-миди, жэкри э(н) мо́.'),['Утром','Во второй половине дня','Время не указано'],1,'Письмо отнесено ко второй половине дня.','Рамка в начале означает время после полудня; это не утро.')
intro(s,2,'Le soir — «вечер; вечером», la nuit — «ночь; ночью». Различайте эти части суток. Образцы: Le soir, je regarde la télé. — «Вечером я смотрю телевизор»; La nuit, je lis un livre. — «Ночью я читаю книгу». Выбирайте время по словам, а не по тому, кажется ли действие типичным для этого времени.',['soir','nuit'],[('Le soir','лё суа́р'),('la nuit','ла нюи́'),('Le soir, je regarde la télé.','лё суар, жё рёгард ла тэле́'),('La nuit, je lis un livre.','ла нюи, жё ли э(н) ли́вр')],('Le soir, je regarde la télé. La nuit, je lis un livre.','лё суар, жё рёгард ла тэле́. ла нюи, жё ли э(н) ли́вр.'))
pairs(s,[U],[('soir','Вечер'),('nuit','Ночь'),('matin','Утро')],'Вы различили вечер, ночь и знакомое утро.','Каждая рамка называет свою часть суток: вечер, ночь или утро.')
listen(s,[U],['soir','nuit','matin','je','regarder','tele'],['soir'],'Когда происходит просмотр по реплике?','Le soir, je regarde la télé.','лё суар, жё рёгард ла тэле́.',['Ночью','Утром','Вечером'],2,'Просмотр отнесён к вечеру.','В начале названа вечерняя рамка; ночь и утро в этой реплике не указаны.')
intro(s,4,'Dormir — «спать». Запоминаем только готовую форму о себе: Je dors la nuit. — «Я сплю ночью». Можно начать с уже знакомой рамки: La nuit, je dors. — «Ночью я сплю». Это два порядка одного короткого сообщения; полную таблицу глагола не вводим.',['dormir'],[('Dormir','дорми́р'),('Je dors la nuit.','жё дор ла нюи́'),('La nuit, je dors.','ла нюи, жё до́р')],('Je dors la nuit. La nuit, je dors.','жё дор ла нюи́. ла нюи, жё до́р.'))
